#!/bin/bash

echo "$(date +"[%b %d %H:%M:%S]#") $(basename "$0") $@" | sudo tee -a "/var/log/go/$(basename "$0").log" >/dev/null

Hostname=$(</etc/hostname)
Version=$(sudo wget https://download.goadmio.com/home/go/update/latest.txt -q -t 1 -T 10 --no-check-certificate -O -)
Version=$(echo "$Version" | sed "s/[^0-9.]//g")

TimeStamp=$(date +%s)
ServerIP=$(curl -s -4 checkip.amazonaws.com)

