sudo sqlite3 -batch -init /root/.sqliterc /var/lib/sqlite/directory.db "CREATE TABLE IF NOT EXISTS Directory (DirectoryID INTEGER PRIMARY KEY,Name TEXT NOT NULL DEFAULT '',Directory TEXT UNIQUE,User TEXT NOT NULL DEFAULT '',Pass TEXT NOT NULL DEFAULT '',Domain TEXT NOT NULL DEFAULT '',Username TEXT NOT NULL DEFAULT '',TimeStamp INTEGER DEFAULT '0')"
