    RebootPassword=$(sudo openssl rand -base64 16 | tr -dc 'A-Za-z0-9' | head -c 16)
    sudo sqlite3 -batch -init /root/.sqliterc /var/lib/sqlite/config.db "INSERT INTO Config (Version,InstallStamp,Hostname,SSH,RebootPassword) VALUES ('$Version','$TimeStamp','$Hostname','Black','$RebootPassword')"

fi

UserCount=$(sudo sqlite3 -batch -init /root/.sqliterc /var/lib/sqlite/user.db "SELECT COUNT(*) FROM User")
if [ "$UserCount" -eq "0" ]; then

    sudo sqlite3 -batch -init /root/.sqliterc /var/lib/sqlite/user.db "INSERT INTO User (Username,UserGroup) VALUES ('root','1')"

fi

MariaDBCount=$(sudo sqlite3 -batch -init /root/.sqliterc /var/lib/sqlite/mariadb.db "SELECT COUNT(*) FROM MariaDB")
if [ "$MariaDBCount" -eq "0" ]; then

    sudo sqlite3 -batch -init /root/.sqliterc /var/lib/sqlite/mariadb.db "INSERT INTO MariaDB (MAX_USER_CONNECTIONS) VALUES ('0')"

fi

APICount=$(sudo sqlite3 -batch -init /root/.sqliterc /var/lib/sqlite/api.db "SELECT COUNT(*) FROM API")
if [ "$APICount" -eq "0" ]; then

    Name="File Manager"
    APIKey=$(sudo openssl rand -base64 16 | tr -dc 'A-Za-z0-9' | head -c 16)
    Command="/go/fm [Domain] login"
    sudo sqlite3 -batch -init /root/.sqliterc /var/lib/sqlite/api.db "INSERT INTO API (Name,APIKey,IP,Command,TimeStamp) VALUES ('$Name','$APIKey','$ServerIP','$Command','$TimeStamp')"

fi

CountryCount=$(sudo sqlite3 -batch -init /root/.sqliterc /var/lib/sqlite/country.db "SELECT COUNT(*) FROM Country")
