    sudo /go/country

fi

BotCount=$(sudo sqlite3 -batch -init /root/.sqliterc /var/lib/sqlite/bot.db "SELECT COUNT(*) FROM Bot")
BotCount=0
if [ "$BotCount" -eq "0" ]; then

    # Good Bots
    GBots="Googlebot|AdsBot|bingbot|YandexBot|Curl|Wget|okhttp|Scrapy|axios|aiohttp|python-requests|Facebot"

    IFS='|' read -ra GBotsArray <<<"$GBots"
    for Name in "${GBotsArray[@]}"; do
        sudo sqlite3 -batch -init /root/.sqliterc /var/lib/sqlite/bot.db "INSERT OR IGNORE INTO Bot (Name,Description,Block,TimeStamp) VALUES ('$Name','$Description','0','$TimeStamp')"
    done

    # Bad Bots
    Bots="360spider|adstxtcrawl|ALittle|AliyunSecBot|AhrefsBot|Amazonbot|Baiduspider|BacklinksExtendedBot|Barkrowler|BLEXBot|Bidtellect|BPImageWalker|Brightbot|Bytespider|CCBot|CallpodKeeper|CheckerBot|CodeFamilia-Extractor|coccocbot|criteo-crawl|DataForSeoBot|DnBCrawl|DoCoMo|DomainProbe|DomainStatsBot|DownloadDemon|dotbot|EmailFinderBot|EmailWolf|emetriqContextualBot|EmbarcaderoURI|everyfeed-spider|Exabot|FAST-WebCrawl|FeedBurner|GenomeCrawlerd|GPTBot|GoogleOther|GulperWeb|IbouBot|imgproxy|InternetMeasurement|isBot|keys-so-bot|KOCMOHABT|L9scan|libredtail-http|libwww-perl|LinkBloom|masscan|MatchorySearch|Mediatoolkitbot|meta-externalagent|meta-webindexer|mj12bot|MojeekBot|NetcraftSurveyAgent|newspaper|OI-Crawl|osee2unifiedRelease|our-bot|PetalBot|Peach|Pinterestbot|Qwantbot|Screaming|searchbot|SeekportBot|SemrushBot|SERankingBacklinksBot|SeznamBot|ShellBot|SiteLockSpider|Sogou|SuperBot|Suspicious|TurnitinBot|VelenPublicWebCrawler|webcrawl|WebCopier|WebZIP|WriterBot|ZoominfoBot|nmap|sqlmap|nikto|Go-http-client|HNAP1|xmlrpc"
    sudo sqlite3 -batch -init /root/.sqliterc /var/lib/sqlite/config.db "UPDATE Config SET Bots='$Bots'"

    IFS='|' read -ra BotsArray <<<"$Bots"
    for Name in "${BotsArray[@]}"; do
        sudo sqlite3 -batch -init /root/.sqliterc /var/lib/sqlite/bot.db "INSERT OR IGNORE INTO Bot (Name,Description,Block,TimeStamp) VALUES ('$Name','$Description','1','$TimeStamp')"
        sudo sqlite3 -batch -init /root/.sqliterc /var/lib/sqlite/bot.db "UPDATE Bot SET Block='1' WHERE Name='$Name'"
    done

fi
